import { readFileSync } from 'node:fs';
import { defineConfig } from 'vite';

const pkg = JSON.parse(readFileSync(new URL('./package.json', import.meta.url), 'utf8')) as { version: string };

export default defineConfig(({ command }) => ({
  clearScreen: false,
  define: { __APP_VERSION__: JSON.stringify(pkg.version) },
  // The browser preview reads scratch/report.json (generated by tokenstats-cli --json).
  publicDir: command === 'serve' ? 'scratch' : false,
  server: { host: '127.0.0.1', port: 4317, strictPort: true, watch: { ignored: ['**/src-tauri/**'] } },
  build: { target: 'es2022', outDir: 'dist', emptyOutDir: true, cssMinify: true, reportCompressedSize: false },
}));
